import{_ as s,a8 as a,o as r,c as l,ah as n,K as i}from"./chunks/framework.D31WLDJp.js";import"./chunks/theme.CP9whvzN.js";const f=JSON.parse('{"title":"note2images 基座选型与产品形态","description":"","frontmatter":{"type":"decision","scope":"文转图记","created":"2026-09-12T00:00:00.000Z","updated":"2026-09-12T00:00:00.000Z","tags":["文转图记","note2images","选型","决策"]},"headers":[],"relativePath":"vault/Memory/Decisions/note2images基座选型与产品形态.md","filePath":"vault/Memory/Decisions/note2images基座选型与产品形态.md","lastUpdated":1789374053000}'),c={name:"vault/Memory/Decisions/note2images基座选型与产品形态.md"};function d(g,e,h,m,_,p){const t=a("NolebaseGitContributors"),o=a("NolebaseGitChangelog");return r(),l("div",null,[e[0]||(e[0]=n('<h1 id="note2images-基座选型与产品形态" tabindex="-1">note2images 基座选型与产品形态 <a class="header-anchor" href="#note2images-基座选型与产品形态" aria-label="Permalink to “note2images 基座选型与产品形态”">​</a></h1><p><strong>日期</strong>：2026-09-12　<strong>项目</strong>：文转图记</p><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to “背景”">​</a></h2><p>需求：将基础文本内容转换成可发布到小红书的图文笔记（图片）。调研 GitHub 20+ 候选项目（三条线：小红书图文生成、Agent Skill 形态、文字转图技术方案）， 需选定一个基座二次开发。</p><h2 id="决策" tabindex="-1">决策 <a class="header-anchor" href="#决策" aria-label="Permalink to “决策”">​</a></h2><ol><li><strong>基座 = op7418/guizang-social-card-skill</strong>（AGPL-3.0，6975★）</li><li><strong>形态 = Agent Skill</strong>（SKILL.md + references + assets + scripts）</li><li><strong>加 AI 文案优化环节</strong>（基座没有）：标题/正文/标签改写后再排版</li><li><strong>功能范围 = 小红书 3:4 轮播 + 公众号封面对</strong>，裁掉 Live Photo（依赖 macOS）与地图组件</li><li><strong>暂不做自动发布</strong>（账号风控风险，先跑通生成链路）</li><li><strong>技能名 = note2images</strong>（表达&quot;笔记转图&quot;通用能力，不绑定小红书）</li></ol><h2 id="理由" tabindex="-1">理由 <a class="header-anchor" href="#理由" aria-label="Permalink to “理由”">​</a></h2><ul><li>技术路线共识：HTML/CSS 排版 + Playwright 截图是中文出图最稳方案 （对比 AI 生图：中文文字易崩；对比 Satori/Pillow：排版全自研）</li><li>guizang 是该流派最成熟资产：28 种版式骨架、10 套主题色板、9 条自动质检规则、 双设计系统；缺点仅 AGPL（个人自用无碍）</li><li>弃选：write-then-publish（自定义许可需确认）、xhs-visual-director（MIT 但依赖 生图模型，中文易错）、自建（工作量×3）、RedInk（CC BY-NC-SA 非商业）</li></ul><h2 id="基座短板及本项目改造" tabindex="-1">基座短板及本项目改造 <a class="header-anchor" href="#基座短板及本项目改造" aria-label="Permalink to “基座短板及本项目改造”">​</a></h2><ol><li>无内置渲染脚本（靠 AI 现场写）→ 新增 <code>scripts/render.mjs</code> 稳定渲染器</li><li>无文案优化 → 新增 <code>references/copywriting-xhs.md</code> + 工作流 Step 2</li><li>体积大且含 macOS 专属内容 → SKILL.md 32KB→8KB，references 16→10 份</li><li>字体仅 CDN → 模板加微软雅黑/宋体本地回退栈</li></ol><h2 id="后续" tabindex="-1">后续 <a class="header-anchor" href="#后续" aria-label="Permalink to “后续”">​</a></h2><p>若决策反转（如换基座/加发布），新建决策笔记并 wikilink 回本篇。</p>',12)),i(t),i(o)])}const S=s(c,[["render",d]]);export{f as __pageData,S as default};
